nextflow_process {

    name "Test Process UNIVERSC"
    script "../main.nf"
    config "./nextflow.config"
    process "UNIVERSC"

    tag "modules"
    tag "modules_nfcore"
    tag "universc"
    tag "seqtk/sample"

    test("universc_10x") {
        def reference
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            reference = extract(modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/universc/homo_sapiens_chr22_reference.tar.gz').resolve('homo_sapiens_chr22_reference')
            run("SEQTK_SAMPLE", alias: "SAMPLE_READ1") {
                script "../../seqtk/sample/main.nf"
                process {
                    """
                    input[0] = [
                        [id: "test"],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/10k_pbmc_cmo/fastqs/gex_1/subsampled_SC3_v3_NextGem_DI_CellPlex_Human_PBMC_10K_1_gex_S2_L001_R1_001.fastq.gz', checkIfExists:true),
                        1000
                    ]
                    """
                }
            }
            run("SEQTK_SAMPLE", alias: "SAMPLE_READ2") {
                script "../../seqtk/sample/main.nf"
                process {
                    """
                    input[0] = [
                        [id: "test"],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/10k_pbmc_cmo/fastqs/gex_1/subsampled_SC3_v3_NextGem_DI_CellPlex_Human_PBMC_10K_1_gex_S2_L001_R2_001.fastq.gz', checkIfExists:true),
                        1000
                    ]
                    """
                }
            }
        }
        when {
            params {
                universc_args = "--chemistry 'SC3Pv3' --description test_10x"
            }
            process {
                """
                input[0] = channel.of([ id:'test', single_end:false ])
                    .combine(SAMPLE_READ1.out.reads.map { meta, read -> read } )
                    .combine(SAMPLE_READ2.out.reads.map { meta, read -> read } )
                    .map { meta, read1, read2 -> [meta, [read1, read2]] }
                input[1] = [ [id: "homo_sapiens_chr22_reference"], file('${reference}') ]
                input[2] = "10x"
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstablePatterns: ["**/*.h5", "**/*.bam*"])).match() }
            )
        }
    }


    test("universc_10x -- stub") {
        options '-stub'
        when {
            params {
                universc_args = ""
            }
            process {
                """
                input[0] = [
                    [id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/10k_pbmc_cmo/fastqs/gex_1/subsampled_SC3_v3_NextGem_DI_CellPlex_Human_PBMC_10K_1_gex_S2_L001_R1_001.fastq.gz',checkIfExists:true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/10k_pbmc_cmo/fastqs/gex_1/subsampled_SC3_v3_NextGem_DI_CellPlex_Human_PBMC_10K_1_gex_S2_L001_R2_001.fastq.gz',checkIfExists:true)
                    ]
                ]
                input[1] = [[], []]
                input[2] = [[]]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

process {
    memory = '8.GB' // Fail with "configured to use 15GB of local memory, but only 10.7GB is currently available"
    withName: "UNIVERSC" {
        ext.args = params.universc_args
    }
}
